      "content": "/**\n * dsh-save-money — Client half (official browser bundle, generated by\n * scripts/make-plugin.js from dist/client.js, built from src/client.ts).\n *\n * Loaded automatically by the Web shell: plugin/package.json declares\n * dsh.client + exports[\"./client\"], client-modules serves this file at\n * /plugins/dsh-save-money/client.js and the browser mounts it on startup —\n * no dynamic-plugin step or approval needed.\n */\n\nwindow.__ModuleLoader__.load({\n  id: 'dsh-save-money',\n  factory: (require) => {\n    var module = { exports: {} };\n    var exports = module.exports;\n    const React = require('react');\n    var plugin = (() => {\n// Language is reactive: currentLang starts from browser detection and is\n// overridden by the persisted config choice ('zh'/'zh-TW'/'en'/...) or kept on\n// 'auto' (follow the browser) — see refresh() below and the settings dropdown.\nlet currentLang = detectLang();\n// Plugin name + version shown next to the Save button in the settings popover.\n// '1.4.4' is replaced at build time (scripts/build.js) with the real\n// version from package.json — never edit this literal by hand.\nconst PLUGIN_VERSION = '1.4.4';\n// Local translator bound to the reactive language.\nconst translate = (key, vars) => t(currentLang, key, vars);\n/**\n * dsh-save-money — Pure scheduling/time logic (single source of truth).\n *\n * All timezone conversion, window matching and validation helpers live here as\n * plain exported functions so they can be unit-tested (tests/core.test.js) and\n * are inlined into the Host plugin body at build time (scripts/build.js).\n * Nothing in this module touches Cordis, services, or the sandbox.\n */\n/** Convert a Date to wall-clock components in the given IANA timezone. */\nfunction wallClock(tz, date) {\n    const f = new Intl.DateTimeFormat('en-US', {\n        timeZone: tz, hour12: false,\n        year: 'numeric', month: '2-digit', day: '2-digit',\n        hour: '2-digit', minute: '2-digit', second: '2-digit',\n    });\n    const parts = {};\n    for (const p of f.formatToParts(date))\n        parts[p.type] = p.value;\n    const y = Number(parts.year), mo = Number(parts.month), d = Number(parts.day);\n    const weekday = new Date(Date.UTC(y, mo - 1, d)).getUTCDay();\n    const minutes = Number(parts.hour) * 60 + Number(parts.minute);\n    return { y, mo, d, weekday, minutes };\n}\n/** Parse \"HH:mm\" into minutes-of-day, or null when invalid. */\nfunction parseHHMM(s) {\n    const m = /^(\\d{1,2}):(\\d{2})$/.exec(String(s).trim());\n    if (!m)\n        return null;\n    const h = Number(m[1]), mi = Number(m[2]);\n    if (h > 23 || mi > 59)\n        return null;\n    return h * 60 + mi;\n}\n/** Sunday (0) → 7 so ISO weekday numbering is 1..7. */\nfunction dowNum(wd) { return wd === 0 ? 7 : wd; }\n/** True when the window is active at the given wall-clock time. */\nfunction windowMatchesAt(w, wc) {\n    if (w.days && w.days.length && !w.days.includes(dowNum(wc.weekday)))\n        return false;\n    const p = parseHHMM(w.pauseAt), r = parseHHMM(w.resumeAt);\n    if (p === null || r === null || p === r)\n        return false;\n    const m = wc.minutes;\n    if (p < r)\n        return m >= p && m < r;\n    return m >= p || m < r;\n}\n/** Next pause offset (in days and minutes-of-day) for a window, or null. */\nfunction nextPause(w, tz, wc) {\n    const p = parseHHMM(w.pauseAt), r = parseHHMM(w.resumeAt);\n    if (p === null || r === null || p === r)\n        return null;\n    for (let off = 0; off <= 8; off++) {\n        const d = new Date(Date.UTC(wc.y, wc.mo - 1, wc.d + off));\n        const wd = dowNum(d.getUTCDay());\n        if (w.days && w.days.length && !w.days.includes(wd))\n            continue;\n        if (off === 0) {\n            if (p > wc.minutes)\n                return { dayOffset: 0, minutes: p };\n            continue;\n        }\n        return { dayOffset: off, minutes: p };\n    }\n    return null;\n}\n/**\n * Convert a wall-clock HH:mm on a given date to an epoch-ms UTC instant.\n * Robust for any real offset (incl. ±12/±13h like Pacific/Auckland): first\n * align the wall-clock DATE (full-day steps), then align the minutes within\n * that day — forward-only stepping would cross days for large offsets.\n */\nfunction wallToUTC(tz, y, mo, d, hhmm) {\n    let ms = Date.UTC(y, mo - 1, d, Math.floor(hhmm / 60), hhmm % 60);\n    const targetDay = Date.UTC(y, mo - 1, d);\n    for (let i = 0; i < 8; i++) {\n        const w = wallClock(tz, new Date(ms));\n        if (w.y === y && w.mo === mo && w.d === d && w.minutes === hhmm)\n            return ms;\n        const curDay = Date.UTC(w.y, w.mo - 1, w.d);\n        const dayDiff = Math.round((curDay - targetDay) / 86400000);\n        if (dayDiff !== 0) {\n            ms -= dayDiff * 86400000;\n            continue;\n        }\n        ms += (hhmm - w.minutes) * 60000;\n    }\n    return ms;\n}\n/** Format minutes-of-day as \"HH:mm\" (zero-padded). */\nfunction formatHHMM(m) {\n    const h = Math.floor(m / 60);\n    const mi = m % 60;\n    return String(h).padStart(2, '0') + ':' + String(mi).padStart(2, '0');\n}\n/**\n * Convert a wall-clock HH:mm from one IANA timezone to another, using the\n * given reference date (default: now) so real timezone rules apply\n * (daylight-saving aware). The result keeps the same absolute instant:\n * Beijing 08:58 on a summer day becomes London 01:58, on a winter day 00:58.\n */\nfunction convertHHMM(tzFrom, tzTo, hhmm, ref) {\n    const date = ref || new Date();\n    const wc = wallClock(tzFrom, date);\n    const ms = wallToUTC(tzFrom, wc.y, wc.mo, wc.d, hhmm);\n    return wallClock(tzTo, new Date(ms)).minutes;\n}\n/**\n * UTC offset of a timezone at the given instant, in minutes (DST-aware).\n * Correct at minute precision: interpret the timezone's wall-clock minute as\n * if it were UTC, and subtract the real UTC instant that wall-clock minute\n * maps to. E.g. Asia/Shanghai -> 480, Europe/London -> 60 in summer / 0 in\n * winter, America/New_York -> -240 in summer / -300 in winter.\n */\nfunction utcOffsetMinutes(tz, date) {\n    const wc = wallClock(tz, date);\n    const tzMs = wallToUTC(tz, wc.y, wc.mo, wc.d, wc.minutes);\n    const utcMs = Date.UTC(wc.y, wc.mo - 1, wc.d, Math.floor(wc.minutes / 60), wc.minutes % 60);\n    return Math.round((utcMs - tzMs) / 60000);\n}\n/** True when the string is a valid IANA timezone name. */\nfunction isValidTz(tz) {\n    try {\n        new Intl.DateTimeFormat('en-US', { timeZone: tz });\n        return true;\n    }\n    catch (e) {\n        return false;\n    }\n}\n/** Window as half-open minute ranges (handles midnight-crossing). */\nfunction rangesOf(w) {\n    const p = parseHHMM(w.pauseAt), r = parseHHMM(w.resumeAt);\n    if (p < r)\n        return [[p, r]];\n    return [[p, 1440], [0, r]];\n}\nfunction rangesIntersect(a, b) {\n    for (const sa of a)\n        for (const sb of b) {\n            if (sa[0] < sb[1] && sb[0] < sa[1])\n                return true;\n        }\n    return false;\n}\nfunction daysOverlap(a, b) {\n    const da = (a.days && a.days.length) ? a.days : [1, 2, 3, 4, 5, 6, 7];\n    const db = (b.days && b.days.length) ? b.days : [1, 2, 3, 4, 5, 6, 7];\n    return da.some((d) => db.includes(d));\n}\n/**\n * Validate a windows array: shape, HH:mm syntax, pause != resume, IANA\n * timezone, days 1-7, and same-timezone overlap (incl. midnight-crossing and\n * weekday-intersection cases).\n */\nfunction validateWindows(windows, defaultTz) {\n    if (!Array.isArray(windows))\n        return { ok: false, error: 'windows must be an array' };\n    for (const w of windows) {\n        if (!w || typeof w !== 'object')\n            return { ok: false, error: 'window must be an object' };\n        if (parseHHMM(w.pauseAt) === null || parseHHMM(w.resumeAt) === null) {\n            return { ok: false, error: 'bad HH:mm in window ' + JSON.stringify(w) };\n        }\n        if (parseHHMM(w.pauseAt) === parseHHMM(w.resumeAt)) {\n            return { ok: false, error: 'pauseAt == resumeAt in window ' + JSON.stringify(w) };\n        }\n        if (w.timezone !== undefined && !isValidTz(w.timezone)) {\n            return { ok: false, error: 'invalid IANA timezone: ' + w.timezone };\n        }\n        if (w.days !== undefined && (!Array.isArray(w.days) || !w.days.every((d) => Number.isInteger(d) && d >= 1 && d <= 7))) {\n            return { ok: false, error: 'days must be array of 1-7' };\n        }\n    }\n    for (let i = 0; i < windows.length; i++) {\n        for (let j = i + 1; j < windows.length; j++) {\n            const a = windows[i], b = windows[j];\n            const aTz = a.timezone || defaultTz, bTz = b.timezone || defaultTz;\n            if (aTz !== bTz)\n                continue;\n            if (!daysOverlap(a, b))\n                continue;\n            if (rangesIntersect(rangesOf(a), rangesOf(b))) {\n                return { ok: false, error: 'overlapping windows: ' + JSON.stringify(a) + ' vs ' + JSON.stringify(b) };\n            }\n        }\n    }\n    return { ok: true };\n}\n/**\n * dsh-save-money — Account balance display (host of the header balance UI).\n *\n * Kept as a separate module (inlined into the Client plugin body by\n * scripts/build.js, exactly like src/core.ts) so the feature can grow without\n * bloating the main plugin body. Pure functions only — no React import, no\n * globals — so it stays unit-testable and works in both the dynamic-plugin\n * sandbox and the official bundle form (React is passed in by the caller).\n */\n/** Currency symbol lookup — the API reports CNY/USD, but map any known ISO 4217 code. */\nconst CURRENCY_SYMBOLS = {\n    CNY: '¥',\n    JPY: '¥',\n    KRW: '₩',\n    USD: '$',\n    HKD: 'HK$',\n    SGD: 'S$',\n    TWD: 'NT$',\n    EUR: '€',\n    GBP: '£',\n    CHF: 'CHF',\n    AUD: 'A$',\n    CAD: 'C$',\n    NZD: 'NZ$',\n    RUB: '₽',\n    INR: '₹',\n    BRL: 'R$',\n    MXN: 'MX$',\n};\n/** Extract the displayable balance from a raw /save-money/balance response, or null. */\nfunction pickBalance(raw) {\n    if (!raw || typeof raw !== 'object' || raw.ok !== true)\n        return null;\n    if (!Array.isArray(raw.balance) || raw.balance.length === 0)\n        return null;\n    const b = raw.balance[0];\n    if (!b || typeof b !== 'object')\n        return null;\n    // `?? ''` (not `|| ''`): a literal 0 / empty string is a valid value and\n    // must not be replaced by the fallback.\n    return {\n        currency: String(b.currency ?? ''),\n        total: String(b.total ?? ''),\n        granted: String(b.granted ?? ''),\n        toppedUp: String(b.toppedUp ?? ''),\n    };\n}\n/** Currency symbol for the balance display (CNY → ¥, USD → $, …); unknown → $ fallback. */\nfunction currencySymbol(currency) {\n    return CURRENCY_SYMBOLS[currency] || '$';\n}\n/** The hover detail text (total / granted / topped-up). */\nfunction balanceTitle(b) {\n    const sym = currencySymbol(b.currency);\n    return sym + ' total ' + b.total\n        + (b.granted !== undefined ? ' (granted ' + b.granted + ', topped-up ' + b.toppedUp + ')' : '');\n}\n/** Format one spend value: spent → \"¥1.25\", recovered → \"+¥1.25\", n/a → \"–\". */\nfunction fmtSpend(v, sym) {\n    if (v === null || v === undefined)\n        return '\\u2013'; // en dash — history not yet sampled\n    const n = Number(v);\n    if (!Number.isFinite(n))\n        return '\\u2013';\n    // Positive = spent (shows \"¥1.23\"); negative = balance recovered (shows \"+¥1.23\")\n    return (n >= 0 ? '' : '+') + sym + Math.abs(n).toFixed(2);\n}\n/**\n * The multi-line hover detail for the balance card, or null when the balance\n * is unavailable. Line 0 is the balance summary; then ONE LINE PER spend\n * window — 10m / 1h / 24h — always present so the user can see the features\n * exist. A window whose history is not yet sampled (first ~5 minutes after\n * enabling the display) shows \"–\" instead of a value; `labels` provides the\n * i18n texts (e.g. the localized \"Last 1h spend\").\n *\n * `ranges` (when supplied) carries the wall-clock start instants of each\n * window (m10 / h1 / h24, ms). The client renders them as a time suffix so\n * the rolling spend windows are explicit — e.g. \"Last 1h spend 07:00–08:00 ¥1.25\" —\n * matching the bar chart's explicit \"07:40–07:50\" windows instead of leaving\n * two different \"10 minutes\" unlabeled and confusing.\n *\n * The client renders these lines in its own card (native `title` tooltips get\n * clipped at the viewport edge and cannot wrap, which is why the single-line\n * title is no longer used).\n */\nfunction balanceDetailLines(balance, labels, ranges) {\n    const b = pickBalance(balance);\n    if (!b)\n        return null;\n    const sym = currencySymbol(b.currency);\n    const lines = [balanceTitle(b)];\n    const s = balance && typeof balance === 'object' && balance.spend && typeof balance.spend === 'object' ? balance.spend : null;\n    if (s) {\n        const h1 = fmtSpend(s.h1, sym);\n        const m10 = fmtSpend(s.m10, sym);\n        const h24 = fmtSpend(s.h24, sym);\n        // Every window line is always rendered; unsampled history shows \"–\".\n        // ranges carry window START instants → append \"HH:mm–HH:mm\" via a\n        // caller-supplied formatter (kept out of this pure module: it has no tz).\n        lines.push((labels ? labels.h1 : '1h') + ' ' + h1);\n        lines.push((labels ? labels.m10 : '10m') + ' ' + m10);\n        lines.push((labels ? labels.h24 : '24h') + ' ' + h24);\n    }\n    return lines;\n}\n/**\n * Build the React element for the header balance text, or null when the\n * balance is unavailable (no credential / request failed / not the official\n * DeepSeek API). React is passed in — never imported.\n *\n * The text color uses the theme alias token --dsw-alias-label-secondary (the\n * same secondary-label token the Session Log uses), so it adapts to light and\n * dark mode automatically. No `title` attribute: the full detail (balance +\n * spend) is rendered by the caller in a custom hover card from\n * balanceDetailLines(), because native tooltips get clipped at the viewport\n * edge.\n */\nfunction renderBalanceElement(balance, React) {\n    const b = pickBalance(balance);\n    if (!b)\n        return null;\n    return React.createElement('span', {\n        style: {\n            color: 'var(--dsw-alias-label-secondary)',\n            fontSize: '14px', fontWeight: 600, whiteSpace: 'nowrap',\n            marginRight: '8px', pointerEvents: 'auto', cursor: 'default',\n        },\n    }, currencySymbol(b.currency) + b.total);\n}\nconst zh = {\n    badgeDisabled: '未启用',\n    badgePaused: '已经暂停',\n    badgeWarn: '即将暂停',\n    badgeWorking: '工作中',\n    bannerPaused: '⛔ 已暂停：模型请求已挂起，不产生费用。',\n    bannerAutoResume: ' 自动继续',\n    bannerWarn: '⏳ 距离暂停还有 ',\n    bannerMinutes: ' 分钟',\n    bannerMoment: '片刻',\n    endThisWindow: '结束本次省钱模式',\n    endWindowActive: '✅ 您已结束本次省钱模式：窗口 {a}-{b} 已跳过，{c} 自动恢复省钱（重新关闭再勾选「启用」可重置）',\n    statusPrefix: '状态：',\n    windowSuffix: '（{a}-{b}）',\n    pausedNote: '暂停窗口内所有模型请求在发出前被挂起（不产生费用），窗口结束自动继续，上下文不受影响；点「结束本次省钱模式」可立即恢复并跳过本窗口（只影响当前窗口，下一窗口照常生效）。',\n    deepseekPreset: '一键 DeepSeek 分时计价省钱策略',\n    presetExists: 'DeepSeek 预设两组窗口（含 2 分钟余量）已存在，未重复添加。勾选「启用」即可生效。',\n    presetUpgraded: '已升级 {n} 组旧窗口为带余量窗口；',\n    presetAdded: '已添加 {n} 组 DeepSeek 预设窗口（未启用，请自行勾选「启用」）。',\n    applyFailed: '一键应用失败：',\n    savedMsg: '已保存 {n} 组窗口。',\n    enable: '启用',\n    timezone: '时区',\n    language: '语言',\n    langAuto: '自动（跟随浏览器）',\n    langZh: '中文',\n    langZhTw: '中文（繁體）',\n    langEn: 'English',\n    langDe: 'Deutsch',\n    langFr: 'Français',\n    langEs: 'Español',\n    langIt: 'Italiano',\n    langPt: 'Português',\n    langJa: '日本語',\n    langKo: '한국어',\n    windowsTitle: '暂停窗口（{tz} 墙上时间，共 {n} 组）',\n    pause: '暂停',\n    resume: '继续',\n    removeTitle: '删除该组',\n    addWindow: '+ 添加窗口',\n    save: '保存',\n    settingsTitle: '省钱插件设置',\n    headerTitle: 'save-money：{status}（点击进入设置）',\n    badgeLabel: '省钱